const TRANSLATABLE_ATTRIBUTES = ["title", "aria-label", "placeholder", "alt"];
// English is the source language and the product default (initI18n resolves to
// stored ?? "en"). The pre-init default must match, or any uiText()/translate
// call that runs at module load — before initI18n() fires in DOMContentLoaded —
// silently renders Japanese regardless of the user's language setting.
let currentLocale = "en";
const localeListeners = new Set();
const textOriginalMap = new WeakMap();
const attributeOriginalMap = new WeakMap();
let observer = null;
